def wrapper_identity(path):
    controls.equivalent_wrappers(path)
    p=controls.dependency.oracle.image_pages(path,controls.BASES[0]);base=controls.BASES[0]
    assert controls._read_span(p,base+WRAPPER,32)==bytes.fromhex('fe0f1ff8090840f90a2040a901604039e00309aa40013fd6fe0741f8c0035fd6')
    return dict(byte_count=32,complete_wrapper_stream_equal_to_accepted_token_wrapper=True,no_PC_relative_instructions=True)

def length_42_control(path,libc,base,hexadecimal):
    d=controls.dependency;p,packed,out=d.fresh(path,base,'hex_warm' if hexadecimal else 'raw_warm')
    payload=bytes(range(42));d.dependency.w(p,d.OBJ+8,43,4);d.dependency.w(p,d.OBJ+12,42,4);d._write_span(p,d.DATA,payload+b'\0')
    table=d.dependency.u(p,base+controls.diagnostics.TABLE);d.dependency.w(p,table,0)
    memory,watch,expected_scopes,expected=controls.original(path,libc,base,p,packed)
    actual=d.dependency.Services();scopes=[];leave=controls.diagnostics.leave_diagnostic_scope
    def record(p,**kw):
        a=kw['object_address'];scopes.append((a,d._read_span(p,a,24)));return leave(p,**kw)
    controls.diagnostics.leave_diagnostic_scope=record
    try:
        result=controls.token.apply_token_digest_callback(p,argument_block_address=packed,image_base=base,entry_stack_address=d.SP,
            thread_pointer=d.TP,thread_id=137,allocate=actual.malloc,reallocate=actual.effects.realloc,free=actual.free,observer=actual.diagnostic)
    finally:controls.diagnostics.leave_diagnostic_scope=leave
    assert d._read_span(p,d.G,0xA000)==memory and all(d._read_span(p,a,n)==raw for (a,n),raw in watch.items())
    assert scopes==expected_scopes and actual.events==expected.events
    assert actual.effects.calls==expected.effects.calls and actual.effects.blocks==expected.effects.blocks and actual.freed==expected.freed
    assert result==int.from_bytes(d._read_span(p,out,8),'little')
    expected_digest=hashlib.md5(payload).hexdigest().encode() if hexadecimal else hashlib.md5(payload).digest()
    length=int.from_bytes(d._read_span(p,result+12,4),'little');pointer=int.from_bytes(d._read_span(p,result+16,8),'little')
    assert length==len(expected_digest) and d._read_span(p,pointer,length)==expected_digest
    label=('hex' if hexadecimal else 'raw')+'_42_warm_empty_slot'
    print('PASS second digest',hex(base),label,flush=True)
    return dict(image_base=hex(base),case=label,original_wrapper_digest_and_reference_lifecycle_returned=True,
        complete_wrapper_stream_equal_to_accepted_token_wrapper=True,all_guest_image_packed_and_defined_scratch_bytes_equal=True,
        scope_exit_bytes_equal=True,ordered_allocator_free_mutex_gettid_and_prefree_bytes_equal=True,
        actual_matching_libc_recursive_mutexes=True,native_snapshot_input=False,native_physical_X0_compared=False,
        independently_prepared_source_length=42,warm_global_and_empty_target_slot=True,MD5_payload_matches_independent_input=True)

class PostPairMD5Scenario(previous.PostFormatterPairScenario):
    def __init__(self,control):
        super().__init__(control)
        self._md5_active=False;self._md5_done=False;self._md5_returned=False;self._md5_output_ready=False;self._md5_raw_verified=False
        self._md5_trace=[];self._md5_code={};self._md5_rows=[];self._md5_writes=[];self._md5_violations=[];self._md5_services=[]
        self._md5_ref_events=[];self._md5_pending_refs=[];self._md5_scope_events=[];self._md5_pending_scopes=[];self._md5_allowed_slots=set()
        self._md5_raw_event={};self._md5_raw_return=None

    def _md5_track(self,cpu,pc):
        assert len(self._md5_trace)<300000
        key=self._fmt_site(pc);self._md5_trace.append(key);self._md5_code[key]=bytes(cpu.mem_read(pc,4)).hex()

    def _md5_table_state(self,cpu):
        raw=bytes(cpu.mem_read(self._md5_table,0x800));changes=[]
        for i in range(256):
            if raw[i*8:i*8+8]!=self._md5_table_before[i*8:i*8+8]:
                pointer=int.from_bytes(raw[i*8:i*8+8],'little');entry=bytes(cpu.mem_read(pointer,48)) if pointer else b''
                row=dict(index=i,slot=hex(self._md5_table+i*8),entry=hex(pointer),entry_sha256=raw_hash(entry))
                if pointer:row.update(mutex_state_u16=self._u(cpu,pointer+8,2),owner_u32=self._u(cpu,pointer+12,4),
                    entry_vtable_offset=hex(self._u(cpu,pointer)-self.image),entry_outside_header_sha256=raw_hash(entry[:8]+entry[16:]))
                changes.append(row)
        return dict(address=hex(self._md5_table),width=0x800,sha256=raw_hash(raw),changed_slots=changes,
            global_lock_address=hex(self._md5_global_lock),global_lock_sha256=raw_hash(bytes(cpu.mem_read(self._md5_global_lock,48))))

    def _md5_reference(self,cpu,address):
        raw=bytes(cpu.mem_read(address,16));pointer=self._u(cpu,address);counter=self._u(cpu,address+8)
        row=dict(address=hex(address),pair_sha256=raw_hash(raw),object_address=hex(pointer),counter_address=hex(counter))
        if pointer:
            assert counter
            row.update(counter_u32=self._u(cpu,counter,4),string_object=self._pair_object(cpu,pointer))
        return row

    def _md5_live(self,cpu):
        state=self._pair_live(cpu)
        for key in ('diagnostic',):state.pop(key)
        state['protected_regions_sha256']=digest([dict(label=label,address=hex(a),size=n,sha256=raw_hash(bytes(cpu.mem_read(a,n)))) for label,a,n in self._md5_fixed])
